import {validateMessage} from './validation.js';

// @spec specs/hal-engine-conversation-list/spec.md#42
it('preserves valid list cursors and refuses malformed cursor fields', () => {
  const cursors = [
    {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'},
    {sessionId: 'a'.repeat(128), updatedAt: 0},
  ];
  const invalid = [
    null,
    [],
    'not-an-object',
    {},
    {sessionId: '', updatedAt: 0},
    {sessionId: 'a'.repeat(129), updatedAt: 0},
    {sessionId: 1, updatedAt: 0},
    {sessionId: 's1', updatedAt: 'not-a-date'},
    {sessionId: 's1', updatedAt: true},
    {sessionId: 's1', updatedAt: Infinity},
    {sessionId: 's1', updatedAt: 1e20},
  ];
  expect({
    accepted: cursors.map(before =>
      validateMessage({type: 'list_sessions', limit: 10, before: {...before, userId: 'other'}, userId: 'other'}),
    ),
    withoutLimit: validateMessage({type: 'list_sessions', before: cursors[0]}),
    rejected: invalid.map(before => validateMessage({type: 'list_sessions', before})),
  }).toEqual({
    accepted: cursors.map(before => ({valid: true, data: {type: 'list_sessions', limit: 10, before}})),
    withoutLimit: {valid: true, data: {type: 'list_sessions', before: cursors[0]}},
    rejected: invalid.map(() => ({valid: false, error: expect.stringContaining('before')})),
  });
});
EOF
